#include <stdio.h>
#include <string.h>
#include "vr1_export_obj.h"

void vr1_fprint_fx(FILE *f, vr1_fx v)
{
    char buf[48];
    vr1_fx_to_ascii(v, buf, (int)sizeof(buf), 5);
    fputs(buf, f);
}

static void vr1_print_vec3(FILE *f, vr1_vec3 v)
{
    vr1_fprint_fx(f, v.x);
    fputc(' ', f);
    vr1_fprint_fx(f, v.y);
    fputc(' ', f);
    vr1_fprint_fx(f, v.z);
}

static void vr1_print_vec2(FILE *f, vr1_vec2 v)
{
    vr1_fprint_fx(f, v.x);
    fputc(' ', f);
    vr1_fprint_fx(f, v.y);
}

int vr1_export_obj(FILE *f, const vr1_scene *s, const char *object_name)
{
    long i;

    if (f == 0 || s == 0) return 0;
    fprintf(f, "# Generated by vrml1_wrl_c89_codec\n");
    if (s->info_count > 0 || s->anchor_count > 0 || s->inline_count > 0) {
        fprintf(f, "# VRML1 metadata: infos=%d anchors=%d inlines=%d\n", s->info_count, s->anchor_count, s->inline_count);
    }
    fprintf(f, "o %s\n", object_name != 0 ? object_name : "vrml1_scene");
    for (i = 0; i < s->vertex_count; i++) {
        fputs("v ", f);
        vr1_print_vec3(f, s->vertices[i].pos);
        fputc('\n', f);
    }
    for (i = 0; i < s->point_count; i++) {
        fputs("v ", f);
        vr1_print_vec3(f, s->points[i].pos);
        fputc('\n', f);
    }
    for (i = 0; i < s->vertex_count; i++) {
        fputs("vt ", f);
        vr1_print_vec2(f, s->vertices[i].uv);
        fputc('\n', f);
    }
    for (i = 0; i < s->vertex_count; i++) {
        fputs("vn ", f);
        vr1_print_vec3(f, s->vertices[i].normal);
        fputc('\n', f);
    }
    {
        int last_mat;
        last_mat = -32768;
        for (i = 0; i < s->triangle_count; i++) {
            long a;
            long b;
            long c;
            if (s->triangles[i].material != last_mat) {
                fprintf(f, "usemtl mat_%03d\n", s->triangles[i].material);
                last_mat = s->triangles[i].material;
            }
            a = s->triangles[i].a + 1;
            b = s->triangles[i].b + 1;
            c = s->triangles[i].c + 1;
            fprintf(f, "f %ld/%ld/%ld %ld/%ld/%ld %ld/%ld/%ld\n", a, a, a, b, b, b, c, c, c);
        }
        for (i = 0; i < s->line_count; i++) {
            if (s->lines[i].material != last_mat) {
                fprintf(f, "usemtl mat_%03d\n", s->lines[i].material);
                last_mat = s->lines[i].material;
            }
            fprintf(f, "l %ld %ld\n", s->lines[i].a + 1, s->lines[i].b + 1);
        }
        for (i = 0; i < s->point_count; i++) {
            if (s->points[i].material != last_mat) {
                fprintf(f, "usemtl mat_%03d\n", s->points[i].material);
                last_mat = s->points[i].material;
            }
            fprintf(f, "p %ld\n", s->vertex_count + i + 1);
        }
    }
    return 1;
}

int vr1_export_mtl(FILE *f, const vr1_scene *s)
{
    int i;

    if (f == 0 || s == 0) return 0;
    for (i = 0; i < s->material_count; i++) {
        fprintf(f, "newmtl mat_%03d\n", i);
        fputs("Ka ", f);
        vr1_fprint_fx(f, s->materials[i].ambient.r);
        fputc(' ', f);
        vr1_fprint_fx(f, s->materials[i].ambient.g);
        fputc(' ', f);
        vr1_fprint_fx(f, s->materials[i].ambient.b);
        fputc('\n', f);
        fputs("Kd ", f);
        vr1_fprint_fx(f, s->materials[i].diffuse.r);
        fputc(' ', f);
        vr1_fprint_fx(f, s->materials[i].diffuse.g);
        fputc(' ', f);
        vr1_fprint_fx(f, s->materials[i].diffuse.b);
        fputc('\n', f);
        fputs("Ks ", f);
        vr1_fprint_fx(f, s->materials[i].specular.r);
        fputc(' ', f);
        vr1_fprint_fx(f, s->materials[i].specular.g);
        fputc(' ', f);
        vr1_fprint_fx(f, s->materials[i].specular.b);
        fputc('\n', f);
        if (s->materials[i].texture[0] != '\0') fprintf(f, "map_Kd %s\n", s->materials[i].texture);
        fputc('\n', f);
    }
    return 1;
}

void vr1_print_summary(FILE *f, const vr1_scene *s)
{
    if (f == 0 || s == 0) return;
    fprintf(f, "vertices:  %ld\n", s->vertex_count);
    fprintf(f, "triangles: %ld\n", s->triangle_count);
    fprintf(f, "lines:     %ld\n", s->line_count);
    fprintf(f, "points:    %ld\n", s->point_count);
    fprintf(f, "materials: %d\n", s->material_count);
    fprintf(f, "cameras:   %d\n", s->camera_count);
    fprintf(f, "lights:    %d\n", s->light_count);
    fprintf(f, "infos:     %d\n", s->info_count);
    fprintf(f, "anchors:   %d\n", s->anchor_count);
    fprintf(f, "inlines:   %d\n", s->inline_count);
    fprintf(f, "warnings:  %ld\n", s->warning_count);
    fprintf(f, "errors:    %ld\n", s->error_count);
    fprintf(f, "unknown:   %ld\n", s->skipped_unknown_nodes);
    if (s->has_bbox) {
        fputs("bbox_min:  ", f);
        vr1_print_vec3(f, s->bbox_min);
        fputc('\n', f);
        fputs("bbox_max:  ", f);
        vr1_print_vec3(f, s->bbox_max);
        fputc('\n', f);
    }
}
